def common_elements(first, second):
    # Convert the first collection to a set for faster lookup
    set_first = set(first)
    # Use a set to store common elements to avoid duplicates
    common = set()
    # Iterate through the second collection
    for element in second:
        # If the element is in the set_first, it's a common element
        if element in set_first:
            common.add(element)
    # Convert the set of common elements to a list and return it
    return list(common)
